import {createVentureStore} from './data.js?v=studio-3';
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
let state={loading:true,threads:[],messages:[],branches:[],findings:[],decisions:[],experiments:[],researchTasks:[],members:[],discoveries:[],patterns:[],opportunities:[],runs:[]};
let view='studio',threadId='',branchId='',branchTab='overview',legacyTab='discoveries',legacyId='',toastTimer,formSubmit=null,shareLink='',newBranchId='',comparisonId='',previousDraftCopy='';
let recorder=null,recordStream=null,recordTimer=null,recordStart=0,recordChunks=[],audioDraft=null,voiceNotice='',voiceThreadId='';
const draftScope=()=>`venture-studio:${state.user?.uid||'guest'}:${state.ownerUid||'own'}`;
const drafts=new Map();
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const text=v=>Array.isArray(v)?v.map(text).join('\n'):v&&typeof v==='object'?Object.entries(v).map(([k,x])=>`${human(k)}: ${text(x)}`).join('\n'):String(v??'');
const human=v=>String(v||'').replace(/([a-z])([A-Z])/g,'$1 $2').replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());
const safeUrl=value=>{try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}};
const link=(url,title='Source')=>{const u=safeUrl(url);return u?`<a class="source-link" href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(title)} ↗</a>`:''};
const validAudio=v=>/^data:audio\/[a-zA-Z0-9.+-]+(?:;codecs=[a-zA-Z0-9.-]+)?;base64,[A-Za-z0-9+/=]+$/.test(v||'')&&(v||'').length<=600000;
const ago=value=>{const d=new Date(value);if(!Number.isFinite(d.getTime()))return '';const m=Math.max(0,Math.floor((Date.now()-d.getTime())/60000));return m<1?'just now':m<60?`${m}m ago`:m<1440?`${Math.floor(m/60)}h ago`:d.toLocaleDateString(undefined,{month:'short',day:'numeric'})};
const initials=n=>String(n||'?').split(/[\s@]+/).filter(Boolean).slice(0,2).map(v=>v[0]).join('').toUpperCase();
const byTime=(a,b)=>String(a.createdAt||a.updatedAt||'').localeCompare(String(b.createdAt||b.updatedAt||''));
const descending=(a,b)=>byTime(b,a);
const badge=s=>`<span class="state ${esc(s||'exploring')}">${esc(human(s||'exploring'))}</span>`;
const icon=(name,size=18)=>{const paths={studio:'<path d="M5 19V5h5v14M7.5 13c0-7 10-1 10-8M14 5h7m-3.5-3.5v7"/>',discovery:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5M10 7v6m-3-3h6"/>',experiments:'<path d="M9 3h6m-5 0v6L4 19q-1 2 2 2h12q3 0 2-2L14 9V3M7 15h10"/>',changes:'<path d="M4 12a8 8 0 1 0 3-6M4 4v6h6m2-3v5l3 2"/>',members:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3a4 4 0 0 1 3 4v2"/>',plus:'<path d="M12 4v16M4 12h16"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',mic:'<rect x="9" y="3" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/>',branch:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="5" r="2"/><circle cx="6" cy="19" r="2"/><path d="M6 7v10M6 12c7 0 12-1 12-5"/>',refresh:'<path d="M20 8a8 8 0 1 0 0 8M20 3v6h-6"/>',check:'<path d="m5 12 4 4L19 6"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M15 8V3H3v12h5"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.arrow}</svg>`};
function draft(key){const scoped=`${draftScope()}:${key}`;if(drafts.has(scoped))return drafts.get(scoped);try{const s=JSON.parse(localStorage.getItem(scoped)||'{}');drafts.set(scoped,s);return s}catch{return {}}}
function setDraft(key,value){const scoped=`${draftScope()}:${key}`;drafts.set(scoped,value);try{localStorage.setItem(scoped,JSON.stringify(value))}catch{}}
function clearDraft(key){const scoped=`${draftScope()}:${key}`;drafts.delete(scoped);try{localStorage.removeItem(scoped)}catch{}}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4800)}
async function act(task,message){try{await task();if(message)toast(message)}catch(e){toast(e.message||'Could not complete this action. Please try again.')}}
const store=createVentureStore(next=>{const oldScope=draftScope();state=next;if(oldScope!==draftScope()){threadId='';branchId='';if(recorder?.state==='recording')recorder.stop();audioDraft=null;voiceNotice=''}if(!threadId&&state.threads?.length)threadId=[...state.threads].sort(descending).find(t=>t.status==='active')?.id||state.threads[0].id;if(threadId&&!state.threads.some(t=>t.id===threadId)){threadId='';branchId=''}if(branchId&&!state.branches.some(b=>b.id===branchId))branchId='';render()});
state=store.state;render();
function selectedThread(){return state.threads?.find(t=>t.id===threadId)}
function selectedBranch(){return state.branches?.find(b=>b.id===branchId)}
function branchesForThread(){return (state.branches||[]).filter(b=>b.threadId===threadId).sort(byTime)}
function branchCode(b){return b.parentId?'Further branch':'Direction'}
function discussionSwitcher(){return `<div class="discussion-switcher"><label for="discussion-select">Our discussions <span>${state.threads.length}</span></label><select id="discussion-select" aria-label="Switch discussion">${[...state.threads].sort(descending).map(t=>`<option value="${esc(t.id)}" ${t.id===threadId?'selected':''}>${esc(t.title)}</option>`).join('')}</select></div>`}
function branchOverview(b){const rows=branchesForThread();return `<nav class="direction-overview" aria-label="Directions in this discussion"><p class="eyebrow">${rows.length} direction${rows.length===1?'':'s'} · select to explore</p><div>${rows.map(x=>`<button data-branch="${esc(x.id)}" class="${x.id===b.id?'selected':''}" ${x.id===b.id?'aria-current="true"':''}><span>${esc(branchCode(x))}${x.parentId?' ↳':''}</span><b>${esc(x.title)}</b></button>`).join('')}</div></nav>`}
function author(record){return record.authorName||record.createdByName||(record.createdBy===state.user?.uid?state.user?.displayName:'Contributor')||'Contributor'}
function render(){const active=document.activeElement;const focus=active?.dataset?.draftField;const sel=focus&&'selectionStart'in active?[active.selectionStart,active.selectionEnd]:null;const scroll=window.scrollY;app.innerHTML=shell();if(focus){const el=app.querySelector(`[data-draft-field="${CSS.escape(focus)}"]`);if(el){el.focus({preventScroll:true});if(sel)el.setSelectionRange(...sel)}}if(window.scrollY!==scroll)window.scrollTo({top:scroll,behavior:'instant'});}
function shell(){const auth=!!state.user;const labels={studio:'Discussions',discovery:'Outside discovery',experiments:'Experiments',changes:'What changed',members:'People & access'};const title=auth?labels[view]:'Venture Studio';return `<div class="shell"><aside class="rail"><a class="brand" href="./" aria-label="Venture Studio home"><img src="./icon.svg" alt=""><div><b>venture<br>studio</b><small>IDEAS INTO EXPERIENCE</small></div></a><nav class="nav" aria-label="Workspace navigation">${Object.entries(labels).map(([key,label])=>`<button data-view="${key}" class="${view===key?'active':''}" ${view===key?'aria-current="page"':''}>${icon(key)}<span>${label}</span></button>`).join('')}</nav>${auth?`<div class="rail-section"><span class="eyebrow">Our discussions</span><button data-action="new-thread" class="icon-button" aria-label="Start a discussion">${icon('plus',16)}</button></div><div class="threads-index">${[...(state.threads||[])].sort(descending).map(t=>`<button class="thread-link ${t.id===threadId&&view==='studio'?'selected':''}" data-thread="${esc(t.id)}"><span>${esc(t.title)}</span><small>${esc(human(t.status||'active'))} · ${esc(ago(t.updatedAt||t.createdAt))}</small></button>`).join('')||'<p class="empty">Your discussions will live here.</p>'}</div><div class="rail-foot"><div class="avatars"><span class="avatar self" title="${esc(state.user.displayName)}">${esc(initials(state.user.displayName))}</span>${(state.members||[]).slice(0,3).map(m=>`<span class="avatar" title="${esc(m.name||m.email)}">${esc(initials(m.name||m.email))}</span>`).join('')}<span class="meta muted">Shared studio</span></div><p><span class="status-dot ${state.offline?'offline':''}"></span>${state.demo?'Sample · memory only':state.loading?'Loading workspace':state.offline?'Offline · drafts retained':'Connected to workspace'}</p><button class="session-button" data-action="sign-out">${state.demo?'Leave sample':'Sign out'}</button></div>`:''}</aside><main class="main" id="main" tabindex="-1"><header class="topbar ${!auth?'auth-top':''}"><div><p class="eyebrow">${auth?state.demo?'Invented sample workspace':'Our shared discovery studio':'Sachit + Shalini + agents'}</p><h1>${esc(title)}</h1></div><div class="top-actions">${auth?`<button class="quiet" data-action="refresh" aria-label="Refresh workspace">${icon('refresh',17)}</button><button class="primary" ${state.workspaceAvailable===false&&state.error?'disabled aria-disabled="true"':''} data-action="${view==='discovery'?'new-signal':'new-thread'}">${icon('plus',16)} ${view==='discovery'?'Add signal':'New discussion'}</button>`:`<a class="quiet" href="?demo=1">Explore sample ${icon('arrow',16)}</a>`}</div></header>${state.demo?'<div class="demo-banner"><span><b>Sample tour.</b> Invented people and examples. Changes stay in this tab only.</span><a href="./">Exit sample ↗</a></div>':''}${state.error?`<div class="alert error" role="alert"><span>${esc(state.error)}</span><button class="secondary small-button" data-action="refresh">Retry</button></div>`:''}${state.offline?'<div class="alert"><span>You’re offline. Drafts are kept on this device. Reconnect before saving to the shared studio.</span></div>':''}${state.truncated&&Object.values(state.truncated).some(Boolean)?'<div class="alert">This view contains the most recent 500 records per collection. Older records remain stored.</div>':''}${!auth?renderAuth():state.workspaceAvailable===false&&state.error&&view!=='members'?renderUnavailable():state.loading&&!state.threads?.length?'<div class="loading-line" role="status">Loading your discussions and research…</div>':view==='studio'?renderStudio():view==='discovery'?renderDiscovery():view==='experiments'?renderExperiments():view==='changes'?renderChanges():renderMembers()}</main></div>`}
function renderUnavailable(){return `<section class="workspace-unavailable"><p class="eyebrow">Workspace unavailable</p><h2>We couldn’t open this studio.</h2><p>Your account may need access, or this workspace may no longer be shared with you. Your unsaved drafts are still retained on this device.</p><div class="inline-actions"><button class="primary" data-action="refresh">Try again</button><button class="secondary" data-view="members">People & access</button><button class="quiet" data-action="my-workspace">Open my workspace</button></div></section>`}
function renderAuth(){return `<div class="auth-layout"><div class="auth-copy"><p class="eyebrow">Think together. Test what matters.</p><h2>One thought.<br>Several <span>possibilities.</span></h2><p>A shared place to keep your own words, explore different directions, and turn sourced research into the next small experiment.</p><div class="auth-actions"><button class="primary" data-action="sign-in">Continue with Google ${icon('arrow',17)}</button><a class="secondary" href="?demo=1">Try the sample studio</a></div><p class="privacy-note">Your workspace is private. A shared link opens the owner’s studio only after your verified Google account has been given access.</p></div><div class="auth-proof" aria-label="How a thought becomes directions"><div class="auth-thought"><small class="eyebrow">Your original thought</small><p>“Could we build something people need every week?”</p></div><div class="auth-fork"><div class="auth-direction"><small class="eyebrow">A possible direction</small><h3>Help with a recurring task.</h3><p>Keep the hypothesis and the evidence together.</p></div><div class="auth-direction"><small class="eyebrow">Another direction</small><h3>Make the useful part reusable.</h3><p>Compare the possibilities, then choose what to test.</p></div></div><p class="auth-caption">Illustrative questions, not your workspace content.<br>Discussion → directions → research → decision → experiment</p></div></div>`}
function priorities(){const findings=[...(state.findings||[])].sort(descending);const next=branchesForThread().find(b=>['exploring','shortlisted'].includes(b.status));return `<div class="priority-bar" aria-label="Start here"><button class="priority" data-action="resume"><span class="eyebrow">01 / Resume discussion</span><b>${selectedThread()?'Continue our conversation':'Start with a thought'}</b><span>↗</span></button><button class="priority" data-view="changes"><span class="eyebrow">02 / What changed</span><b>${esc(findings[0]?.title||'See the latest shared work')}</b><span>↗</span></button><button class="priority" data-action="next-decision"><span class="eyebrow">03 / Next decision</span><b>${next?'Which direction should we test?':'Bring a direction into focus'}</b><span>↗</span></button></div>`}
function renderStudio(){const t=selectedThread();if(!t)return `${priorities()}<div class="welcome"><p class="eyebrow">Your studio is ready</p><h2>Begin with something you’ve been thinking about.</h2><p>Share a possibility or a question. Keep it open: the sector, offer and customer can emerge from the discussion.</p><button class="primary" data-action="new-thread">Start our first discussion ${icon('arrow',17)}</button><div class="welcome-art"><p class="eyebrow">A shared ambition</p><h3>Steady ₹10–20k a month first.<br>Room for larger things later.</h3><div><div class="welcome-path">Your own words<br><b>Discussion</b></div><div class="welcome-path">Several possibilities<br><b>Directions</b></div><div class="welcome-path">What reality teaches us<br><b>Experiment</b></div></div></div></div>`;const b=selectedBranch(),opportunity=(state.opportunities||[]).find(o=>o.id===t.sourceOpportunityId);return `${discussionSwitcher()}${priorities()}<header class="discussion-head"><div><p class="eyebrow">Our discussion ${badge(t.status||'active')}</p><h2>${esc(t.title)}</h2>${t.summary?`<p class="pre discussion-summary">${esc(t.summary)}</p><details class="mobile-summary"><summary>Shared context</summary><p class="pre">${esc(t.summary)}</p></details>`:''}${t.sourceOpportunityId?`<button class="source-context text-button" data-context-legacy="${esc(t.sourceOpportunityId)}" data-context-collection="opportunities">From opportunity: ${esc(opportunity?.title||'Open source opportunity')} ↗</button>`:''}</div><div class="head-buttons"><button class="quiet small-button" data-action="edit-thread">Edit discussion</button><button class="secondary small-button" data-action="new-branch">${icon('branch',14)} New direction</button></div></header><nav class="workspace-jump" aria-label="Jump to discussion or directions"><button data-action="jump-conversation">The conversation</button><button data-action="jump-directions">Directions <span>${branchesForThread().length}</span></button></nav><div class="workspace ${b?'focused':''}"><section class="conversation" id="conversation" aria-label="Original discussion"><div class="panel-title"><h3>The conversation</h3><small>Original words stay intact</small></div><div class="messages">${(state.messages||[]).filter(m=>m.threadId===threadId&&!m.branchId).sort(byTime).map((m,i)=>renderMessage(m,i)).join('')||'<p class="empty">Add your first thought. It can be a question, a link, or an unfinished idea.</p>'}</div>${renderComposer()}</section><section class="branch-area" id="directions" aria-label="Directions from this discussion"><div class="branch-toolbar"><h3>${b?'Direction in focus':'Where this could go'}</h3><div>${b?`<button class="quiet small-button" data-action="all-branches">${icon('back',14)} All directions</button>`:''}<button class="secondary small-button" data-action="compare">Compare ${icon('arrow',13)}</button></div></div>${b?renderBranchFocus(b):renderBranchMap()}</section></div>`}
function renderMessage(m,i=1){return `<article class="message ${i===0?'source':''}" id="message-${esc(m.id)}"><div class="message-meta"><span class="avatar ${m.createdBy===state.user?.uid?'self':''}">${esc(initials(author(m)))}</span><b>${esc(author(m))}</b><small>${esc(ago(m.createdAt))}</small></div><p class="pre">${esc(m.text)}</p>${link(m.sourceUrl,'Shared source')}${validAudio(m.audioData)?`<audio controls preload="none" src="${esc(m.audioData)}" aria-label="Original voice note by ${esc(author(m))}"></audio><p class="draft-note">Original audio · ${Math.round(Number(m.audioDuration)||0)} seconds · accompanying text above</p>`:''}<div class="message-actions"><button class="text-button" data-action="branch-message" data-id="${esc(m.id)}">${icon('branch',12)} Explore a direction from this</button></div></article>`}
function renderComposer(){const d=draft(`composer:${threadId}`),clip=audioDraft?.threadId===threadId?audioDraft:null,notice=voiceThreadId===threadId?voiceNotice:'';return `<form class="composer" id="composer" data-thread-id="${esc(threadId)}"><label class="visually-hidden" for="thought">Add a thought</label><textarea id="thought" name="text" data-draft-field="thought" placeholder="Add a thought, a question, or a new perspective…" maxlength="12000" required>${esc(d.text||'')}</textarea>${clip?`<div class="voice-preview"><audio controls src="${esc(clip.data)}" aria-label="Preview your voice note"></audio><button type="button" class="icon-button" data-action="discard-audio" aria-label="Discard voice note">${icon('close',16)}</button></div>`:''}<div class="composer-tools"><button type="button" class="voice-button ${recorder?.state==='recording'?'recording':''}" data-action="record">${icon('mic',15)} ${recorder?.state==='recording'?'Stop recording':clip?'Record again':'Voice note'}</button><button class="primary" type="submit">Add thought ${icon('arrow',14)}</button></div>${notice?`<p class="voice-info" role="status">${esc(notice)}</p>`:''}</form><p class="draft-note">${state.demo?'Sample changes stay in memory.':'Unsaved text is retained on this device. Your words are saved after acknowledgment.'} Voice clips: up to 60 seconds, with editable accompanying text.</p>`}
function renderBranchMap(){const rows=branchesForThread();if(!rows.length)return `<div class="branch-empty"><p class="eyebrow">From thought to possibility</p><h3>Give one idea a direction.</h3><p>A direction is a hypothesis, not a commitment. Keep several possibilities open and let the evidence change your view.</p><button class="primary" data-action="new-branch">Explore a direction ${icon('branch',16)}</button></div>`;const result=[],visited=new Set();function walk(b,depth=0){if(visited.has(b.id))return;visited.add(b.id);result.push({...b,depth});rows.filter(c=>c.parentId===b.id).forEach(c=>walk(c,depth+1))}rows.filter(b=>!b.parentId||!rows.some(x=>x.id===b.parentId)).forEach(b=>walk(b));rows.forEach(b=>walk(b));return `<div class="branch-map"><p class="source-caption">From “${esc(selectedThread()?.title)}”. Each sheet keeps its source thought and parent direction.</p>${result.map((b,i)=>{const f=(state.findings||[]).filter(f=>f.branchId===b.id).sort(descending);const task=(state.researchTasks||[]).filter(t=>t.branchId===b.id&&['queued','running'].includes(t.status));const source=(state.messages||[]).find(m=>m.id===b.sourceMessageId);return `<article class="branch-sheet ${b.depth?'child':''} ${b.id===newBranchId?'new-branch':''}" tabindex="0" role="button" data-branch="${esc(b.id)}" aria-label="Open direction: ${esc(b.title)}"><div class="branch-meta"><span class="branch-code">${esc(branchCode(b))}</span>${badge(b.status)}</div>${b.parentId?`<p class="map-lineage">↳ From ${esc(rows.find(x=>x.id===b.parentId)?.title||'parent direction')}</p>`:''}<h3>${esc(b.title)}</h3><p class="pre">${esc(b.hypothesis||b.offer||'Describe what this direction could make possible.')}</p>${source?`<p class="draft-note">From ${esc(author(source))}’s thought: “${esc(String(source.text).slice(0,90))}${String(source.text).length>90?'…':''}”</p>`:''}${f[0]?`<div class="branch-proof ${esc(f[0].stance)}"><b>${esc(human(f[0].stance))} · ${esc(human(f[0].evidenceType))}</b>${esc(f[0].title)}</div>`:''}<footer class="branch-footer"><span>${f.length} finding${f.length!==1?'s':''}${task.length?` · ${task.length} research ${task.some(t=>t.status==='running')?'in progress':'queued'}`:''}</span><span>Open direction ↗</span></footer></article>`}).join('')}</div>`}
function field(label,value,full=false){return `<div class="detail-field ${full?'full':''}"><span>${esc(label)}</span><p class="pre">${esc(text(value)||'Not defined yet')}</p></div>`}
function renderBranchFocus(b){const parent=(state.branches||[]).find(x=>x.id===b.parentId),source=(state.messages||[]).find(x=>x.id===b.sourceMessageId);const tabs={overview:'Direction',research:'Research',decisions:'Decisions',experiments:'Experiments'};return `${branchOverview(b)}<button class="mobile-thread-back" data-action="all-branches">${icon('back',14)} Back to discussion & directions</button><article class="focus-sheet"><header class="focus-header"><div class="focus-lineage">${icon('branch',13)} ${parent?`<button data-branch="${esc(parent.id)}">From ${esc(parent.title)} ↗</button>`:`<span>From “${esc(selectedThread()?.title)}”</span>`}</div><div class="branch-meta"><span class="branch-code">Direction in focus</span>${badge(b.status)}</div><h3>${esc(b.title)}</h3><p class="pre">${esc(b.hypothesis||'What do we believe could work?')}</p>${source?`<div class="branch-proof"><b>Original thought · ${esc(author(source))}</b><span class="pre">${esc(source.text)}</span></div>`:''}</header><nav class="focus-tabs" aria-label="Direction sections">${Object.entries(tabs).map(([key,label])=>`<button data-tab="${key}" class="${branchTab===key?'active':''}" ${branchTab===key?'aria-current="page"':''}>${label}${key==='research'?` · ${(state.findings||[]).filter(f=>f.branchId===b.id).length}`:''}</button>`).join('')}</nav><div class="focus-content">${branchTab==='overview'?`<div class="detail-fields">${field('Who is it for?',b.customer)}${field('What would we offer?',b.offer)}${field('What must be true?',b.assumptions,true)}${field('What don’t we know?',b.openQuestions,true)}</div><div class="inline-actions"><button class="secondary small-button" data-action="edit-branch">Edit direction</button><button class="secondary small-button" data-action="child-branch">${icon('branch',14)} Branch further</button><button class="primary small-button" data-action="research">Ask for research</button></div>`:branchTab==='research'?renderResearch(b):branchTab==='decisions'?renderDecisions(b):renderBranchExperiments(b)}</div></article>`}
function renderResearch(b){const findings=(state.findings||[]).filter(f=>f.branchId===b.id).sort(descending),tasks=(state.researchTasks||[]).filter(t=>t.branchId===b.id).sort(descending);return `<div class="section-heading"><div><h3>Let the evidence push back.</h3><p>Sources, interpretation, and open questions stay distinct.</p></div></div><div class="inline-actions" style="margin:0 0 20px"><button class="primary small-button" data-action="research">Queue research</button><button class="secondary small-button" data-action="finding">Add a finding</button></div>${tasks.map(t=>`<div class="queue-item">${badge(t.status)}<b>${esc(t.question)}</b><p>${t.resultSummary?esc(t.resultSummary):t.status==='queued'?'Queued for an agent to pick up. No agent is currently claimed to be working on this request.':t.status==='running'?'An agent marked this task as running. Published findings will appear below.':t.status==='blocked'?'This research is blocked. Check the question and agent notes.':'Research marked complete.'}</p></div>`).join('')}${findings.map(renderFinding).join('')||'<p class="empty"><b>No findings yet.</b>Ask a focused question or attach evidence. Research can support a direction or challenge it.</p>'}<div class="panel-title" style="margin-top:22px"><h3>Notes on this direction</h3><button class="text-button" data-action="branch-note">Add note</button></div>${(state.messages||[]).filter(m=>m.branchId===b.id).sort(byTime).map(m=>renderMessage(m)).join('')||'<p class="empty">Keep follow-up thoughts attached to this direction.</p>'}`}
function renderFinding(f){return `<article class="finding"><div class="finding-meta"><span class="stance ${esc(f.stance)}">${esc(human(f.stance))}</span>${badge(f.evidenceType||'reported')}<small>${esc(author(f))} · ${esc(f.origin==='agent'||f.createdBy==='venture-agent'||f.createdBy==='sample-agent'?'Agent finding':'Human note')}</small></div><h4>${esc(f.title)}</h4><p class="pre">${esc(f.summary)}</p>${link(f.sourceUrl,f.sourceTitle||'Open source')}${!safeUrl(f.sourceUrl)?'<p class="draft-note">No source attached. Treat this as a note until verified.</p>':''}<small>${esc(ago(f.createdAt))}</small></article>`}
function renderDecisions(b){return `<div class="section-heading"><div><h3>Choose, and keep the why.</h3><p>Every decision stays in the record. A rejection can be revisited.</p></div></div><button class="primary small-button" data-action="decision">Record a decision ${icon('arrow',14)}</button>${(state.decisions||[]).filter(d=>d.branchId===b.id).sort(descending).map(d=>`<article class="decision"><h4>${badge(d.outcome)} ${esc(author(d))}</h4><p class="pre">${esc(d.reason)}</p>${d.revisitWhen?`<p class="draft-note">Revisit when: ${esc(d.revisitWhen)}</p>`:''}<span class="meta">${esc(ago(d.createdAt))}</span></article>`).join('')||'<p class="empty">No decision yet. Compare directions before committing to the next experiment.</p>'}`}
function renderExperiment(e){const b=(state.branches||[]).find(b=>b.id===e.branchId);return `<article class="experiment"><div class="branch-meta"><small class="eyebrow">${esc(b?.title||'An experiment')}</small>${badge(e.status)}</div><h4>${esc(e.title)}</h4><p class="pre">${esc(e.hypothesis)}</p><div class="detail-fields">${field('How we’ll test',e.method)}${field('What counts as success',e.successCriterion)}${e.result?field('What happened',e.result,true):''}${e.learning?field('What we learned',e.learning,true):''}${e.nextStep?field('What happens next',e.nextStep,true):''}</div><div class="inline-actions"><button class="secondary small-button" data-action="edit-experiment" data-id="${esc(e.id)}">${e.status==='completed'?'Review result':'Update / capture result'}</button>${b?`<button class="quiet small-button" data-branch="${esc(b.id)}">Open direction →</button>`:''}</div></article>`}
function renderBranchExperiments(b){const es=(state.experiments||[]).filter(e=>e.branchId===b.id).sort(descending);return `<div class="section-heading"><div><h3>A small test. A useful answer.</h3><p>Results feed the discussion; they don’t silently change a decision.</p></div></div><button class="primary small-button" data-action="experiment">Plan an experiment ${icon('plus',14)}</button>${es.map(renderExperiment).join('')||'<p class="empty">Set a hypothesis, a method and a success criterion before starting.</p>'}`}
function renderExperiments(){return `<div class="content-head"><p class="eyebrow">Reality, brought back to the studio</p><h2>What are we learning?</h2><p>Plan small tests, capture what happened, and decide the next move with the result in view.</p></div><div class="experiment-grid">${[...(state.experiments||[])].sort(descending).map(renderExperiment).join('')||'<div class="empty"><b>No experiments yet.</b>Open a discussion, choose a direction, and plan a small test.<div class="inline-actions"><button class="primary small-button" data-view="studio">Go to discussions</button></div></div>'}</div>`}
function renderOpenResearch(){const tasks=(state.researchTasks||[]).filter(t=>t.scope==='open').sort(descending);const findings=(state.findings||[]).filter(f=>!f.branchId).sort(descending);const unscoped=findings.filter(f=>!f.threadId&&!tasks.some(t=>t.id===f.taskId));if(!tasks.length&&!unscoped.length)return '';return `<section class="open-research" aria-label="Outside research and findings"><div class="section-heading"><div><h3>Research from the outside</h3><p>Published findings stay beside the question they answer.</p></div></div>${tasks.map(t=>{const linked=findings.filter(f=>f.taskId===t.id);return `<article class="open-research-task"><div class="queue-item">${badge(t.status)} <b>${esc(t.question)}</b>${t.resultSummary?`<p class="pre">${esc(t.resultSummary)}</p>`:`<p>${t.status==='queued'?'Queued for an agent to pick up.':t.status==='running'?'An agent marked this research as running.':t.status==='blocked'?'Research is blocked.':'Research marked complete.'}</p>`}</div>${linked.length?`<div class="open-findings">${linked.map(renderFinding).join('')}</div>`:t.status==='completed'?'<p class="draft-note">No individual findings are attached to this task yet.</p>':''}</article>`}).join('')}${unscoped.length?`<div class="open-research-task"><p class="eyebrow">Other outside findings</p><div class="open-findings">${unscoped.map(renderFinding).join('')}</div></div>`:''}</section>`}
function renderDiscovery(){const names={discoveries:'Market signals',patterns:'Patterns',opportunities:'Opportunities',runs:'Research runs'},items=state[legacyTab]||[],item=items.find(x=>x.id===legacyId);return `<div class="content-head"><p class="eyebrow">An independent stream of outside evidence</p><h2>Keep looking beyond our ideas.</h2><p>Existing discoveries, patterns and opportunities remain here. Bring an opportunity into a discussion when you want to explore it together.</p><div class="inline-actions"><button class="primary small-button" data-action="open-research">Queue open discovery</button></div></div><nav class="legacy-tabs" aria-label="Discovery collections">${Object.entries(names).map(([key,label])=>`<button data-legacy-tab="${key}" class="${legacyTab===key?'active':''}">${label}</button>`).join('')}</nav>${renderOpenResearch()}<div class="content-layout"><section class="discovery-list">${items.map((r,i)=>`<button class="legacy-item ${r.id===legacyId?'selected':''}" data-legacy="${esc(r.id)}" data-index="${String(i+1).padStart(2,'0')}">${badge(r.status||'recorded')}<h3>${esc(r.title||r.summary||`Research run · ${ago(r.startedAt)}`)}</h3><p>${esc(r.summary||r.thesis||r.offer||r.resultSummary||r.question||'Open to inspect the stored record.')}</p></button>`).join('')||'<p class="empty">No records in this collection yet. Outside discovery can continue independently of your discussions.</p>'}</section>${item?renderLegacyDetail(item):'<aside class="legacy-detail"><p class="eyebrow">Evidence, before interpretation</p><h3>Select a record to see what it contains.</h3><p class="empty">Source links and existing decisions stay with their records. Estimates are not proven income.</p></aside>'}</div>`}
function renderLegacyDetail(r){const omitted=['id','title','createdBy','authorName','createdAt','updatedAt','updatedBy','revision','status','sources','derivedFrom','discoveryIds','sourceUrl','origin'];const labels={monthlyPotentialMin:'Monthly income estimate · minimum',monthlyPotentialMax:'Monthly income estimate · maximum',ourAngle:'Our angle · interpretation',initialThought:'Original interpretation'};return `<aside class="legacy-detail"><div class="branch-meta"><p class="eyebrow">${esc(human(legacyTab))}</p>${badge(r.status||'recorded')}</div><h3>${esc(r.title||r.summary||'Stored research run')}</h3><dl>${Object.entries(r).filter(([k,v])=>!omitted.includes(k)&&v!==''&&v!==null).map(([k,v])=>`<dt>${esc(labels[k]||human(k))}</dt><dd>${esc(text(v))}</dd>`).join('')}</dl>${(r.sources||[]).map(s=>link(s.url,s.title||s.publisher||'Source')).join('')}${link(r.sourceUrl,'Primary source')}${(r.derivedFrom||r.discoveryIds||[]).length?`<dl><dt>Linked market evidence</dt>${(r.derivedFrom||r.discoveryIds).map(id=>{const d=(state.discoveries||[]).find(d=>d.id===id);return `<dd>${esc(d?.title||id)} ${d?link(d.sourceUrl,'Source'):''}</dd>`}).join('')}</dl>`:''}${legacyTab==='opportunities'?`<p class="draft-note">Any income range in this record is an estimate. Check its assumptions against real customer evidence.</p><div class="inline-actions"><button class="primary small-button" data-action="discuss-opportunity">Discuss this opportunity</button><button class="secondary small-button" data-action="legacy-decision">Record a decision</button></div>`:legacyTab==='discoveries'?'<div class="inline-actions"><button class="secondary small-button" data-action="legacy-decision">Record status & reason</button></div>':''}</aside>`}
function renderChanges(){const entries=[...(state.messages||[]).map(r=>({...r,type:'thought',title:r.text})),...(state.branches||[]).map(r=>({...r,type:'direction'})),...(state.findings||[]).map(r=>({...r,type:'finding'})),...(state.decisions||[]).map(r=>({...r,type:'decision',title:`${human(r.outcome)}: ${r.reason}`})),...(state.experiments||[]).map(r=>({...r,type:'experiment'}))].sort((a,b)=>String(b.updatedAt||b.createdAt||'').localeCompare(String(a.updatedAt||a.createdAt||''))).slice(0,60);return `<div class="content-head"><p class="eyebrow">The shared work, in sequence</p><h2>Pick up where we left off.</h2><p>New thoughts, directions, findings, decisions and experiment results. Each change leads back to the context it belongs to.</p></div><div class="activity-list">${entries.map(r=>`<article class="activity"><small>${esc(human(r.type))} · ${esc(author(r))} · ${esc(ago(r.updatedAt||r.createdAt))}</small><h3>${esc(String(r.title||r.question||'Shared update').slice(0,220))}</h3>${r.type==='finding'?`<p>${esc(r.summary)}</p>${link(r.sourceUrl,r.sourceTitle||'Source')}`:''}${r.type==='experiment'&&r.result?`<p>Result: ${esc(r.result)}</p>`:''}${r.threadId?`<button class="text-button" data-context-thread="${esc(r.threadId)}" data-context-branch="${esc(r.branchId||(r.type==='direction'?r.id:''))}">Return to context →</button>`:r.legacyId?`<button class="text-button" data-context-legacy="${esc(r.legacyId)}" data-context-collection="${esc(r.legacyCollection)}">Open source record →</button>`:''}</article>`).join('')||'<p class="empty">The story of your shared work will appear here.</p>'}</div>`}
function renderMembers(){const url=new URL(location.href);url.search='';url.searchParams.set('workspace',state.ownerUid||'');const unavailable=state.workspaceAvailable===false&&!!state.error,own=state.isOwner&&!unavailable;return `<div class="content-head"><p class="eyebrow">Sachit + Shalini + agents</p><h2>A studio we can share.</h2><p>${unavailable?'This account cannot currently open the selected workspace. Retry, open your own workspace, or use another shared link.':own?'Add a verified Google email to give someone editing access. You control who belongs to this workspace.':'You have editing access to this shared workspace. Only its owner can manage membership.'} A link selects this studio; it does not grant access.</p></div><div class="member-list"><div class="member-row"><span class="avatar self">${esc(initials(state.user?.displayName))}</span><div><b>${esc(state.user?.displayName)}</b><p>${esc(state.user?.email)} · ${unavailable?'Signed in · access unavailable':own?'Workspace owner':'Editor'}</p></div>${badge(unavailable?'signed in':own?'owner':'editor')}</div>${(state.members||[]).filter(m=>m.email!==state.user?.email).map(m=>`<div class="member-row"><span class="avatar">${esc(initials(m.name||m.email))}</span><div><b>${esc(m.name||m.email)}</b><p>${esc(m.email)} · Editor</p></div>${own?`<button class="quiet small-button" data-action="remove-member" data-email="${esc(m.email)}">Remove</button>`:''}</div>`).join('')}${own?'<div class="inline-actions"><button class="primary" data-action="invite">Add a person</button></div>':''}<div class="share-link"><b>Workspace link</b><p>${esc(shareLink||url.href)}</p><button class="text-button" data-action="copy-share">${icon('copy',13)} Copy link</button><p class="draft-note">Share it yourself after access has been added. No invitation email is sent automatically.</p></div><div class="inline-actions"><button class="secondary small-button" data-action="switch-workspace">Open a workspace link</button>${!own?'<button class="quiet small-button" data-action="my-workspace">Return to my workspace</button>':''}</div></div>`}
function formField(f,value){const id=`form-${f.name}`;return `<label class="form-field" for="${id}"><span>${esc(f.label)}${f.required?' *':''}</span>${f.type==='select'?`<select id="${id}" name="${esc(f.name)}" ${f.required?'required':''}>${f.options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,human(o)];return `<option value="${esc(v)}" ${String(value||f.default||'')===v?'selected':''}>${esc(l)}</option>`}).join('')}</select>`:f.type==='textarea'?`<textarea id="${id}" name="${esc(f.name)}" ${f.required?'required':''} maxlength="${f.max||4000}" placeholder="${esc(f.placeholder||'')}">${esc(value||'')}</textarea>`:`<input id="${id}" name="${esc(f.name)}" type="${esc(f.type||'text')}" value="${esc(value||'')}" ${f.required?'required':''} maxlength="${f.max||180}" placeholder="${esc(f.placeholder||'')}">`}${f.help?`<small>${esc(f.help)}</small>`:''}</label>`}
function openForm({key,title,description='',fields,initial={},submit='Save',onSubmit,optionalFrom=null,backAction='close-dialog',backLabel='Close'}){if(dialog.open)dialog.close();const saved=draft(key),baseRevision=initial.revision?Number(initial.revision):null,hasSaved=fields.some(f=>saved[f.name]!==undefined),stale=baseRevision!==null&&hasSaved&&Number(saved.__baseRevision)!==baseRevision;if(stale)setDraft(`previous:${key}`,saved);const previous=stale?saved:draft(`previous:${key}`),hasPrevious=baseRevision!==null&&fields.some(f=>previous[f.name]!==undefined),values={...initial,...(stale?{}:saved)};previousDraftCopy=hasPrevious?fields.filter(f=>previous[f.name]!==undefined).map(f=>`${f.label}:\n${previous[f.name]}`).join('\n\n'):'';const recovery=hasPrevious?`<aside class="draft-recovery"><b>${stale?'This item changed while your draft was open.':'Your earlier draft is still available.'}</b><p>${stale?'The latest shared version is shown below. Your earlier draft has been kept separately; review or copy it before making new edits.':'The fields below contain your current draft. An earlier version is kept here for reference.'}</p><details><summary>Review earlier draft</summary>${fields.filter(f=>previous[f.name]!==undefined).map(f=>`<label class="form-field"><span>${esc(f.label)}</span><textarea readonly aria-label="Earlier draft: ${esc(f.label)}">${esc(previous[f.name])}</textarea></label>`).join('')}<button type="button" class="secondary small-button" data-action="copy-previous-draft">Copy earlier draft</button></details></aside>`:'';dialog.className='';dialog.innerHTML=`<form id="studio-form" data-draft-key="${esc(key)}" ${baseRevision!==null?`data-base-revision="${baseRevision}"`:""}><header class="dialog-head"><div><p class="eyebrow">Shared studio</p><h2 id="dialog-title">${esc(title)}</h2>${description?`<p>${esc(description)}</p>`:''}</div><button type="button" class="icon-button" data-action="close-dialog" aria-label="Close dialog">${icon('close',18)}</button></header><div class="dialog-body">${recovery}${fields.filter((f,i)=>optionalFrom===null||i<optionalFrom).map(f=>formField(f,values[f.name])).join('')}${optionalFrom!==null?`<details class="optional-fields" ${fields.slice(optionalFrom).some(f=>values[f.name])?'open':''}><summary>Add details when you’re ready <span>Optional</span></summary><p>Customer, offer, assumptions and open questions can take shape as you explore.</p>${fields.slice(optionalFrom).map(f=>formField(f,values[f.name])).join('')}</details>`:''}<div id="form-error" hidden class="form-error" role="alert"></div><p class="draft-note">Unsaved text is retained on this device. Closing keeps this draft.</p><div class="dialog-actions"><button type="button" class="secondary" data-action="${esc(backAction)}">${esc(backLabel)}</button><button type="submit" class="primary">${esc(submit)} ${icon('arrow',15)}</button></div></div></form>`;formSubmit=async values=>{await onSubmit(values);clearDraft(key)};syncFormRequirements();dialog.showModal();}
function syncFormRequirements(){const form=dialog.querySelector('#studio-form');if(!form)return;const evidence=form.elements.evidenceType;if(evidence&&form.elements.sourceUrl)form.elements.sourceUrl.required=['fact','reported'].includes(evidence.value);const status=form.elements.status;if(status&&form.elements.result&&form.elements.learning){form.elements.result.required=status.value==='completed';form.elements.learning.required=status.value==='completed'}}
function threadForm(sourceOpportunityId=''){const source=(state.opportunities||[]).find(o=>o.id===sourceOpportunityId);openForm({key:`new-thread:${sourceOpportunityId}`,title:source?'Bring this into a discussion':'Start a discussion',description:'Keep the original thought. You can explore the possibilities together from here.',fields:[{name:'title',label:'What are we thinking about?',required:true,max:180},{name:'text',label:'Your original thought',type:'textarea',required:true,max:12000,placeholder:'A possibility, a question, something you noticed…'},{name:'summary',label:'Shared context (optional)',type:'textarea'}],initial:source?{title:source.title,summary:`Exploring an existing opportunity: ${source.title}`}:{},submit:'Start discussion',onSubmit:async v=>{const r=await store.createThread({...v,sourceOpportunityId});threadId=r.id;branchId='';view='studio';render();toast('Discussion started. Your original words are saved.')}})}
const branchFields=[{name:'title',label:'Give this direction a name',required:true,max:180},{name:'hypothesis',label:'What do we believe could work?',type:'textarea',required:true,placeholder:'We believe [customer] would value [offer] because…'},{name:'customer',label:'Who might it be for?',type:'textarea'},{name:'offer',label:'What might we offer?',type:'textarea'},{name:'assumptions',label:'What must be true?',type:'textarea'},{name:'openQuestions',label:'What don’t we know yet?',type:'textarea'}];
const comparisonFields=['demand','access','repeatability','economics','effort','automation','uncertainty'];
function branchForm({sourceMessageId='',parentId='',edit=false}={}){const b=edit?selectedBranch():null;if(!selectedThread()){threadForm();return}const revision=b?.revision||1;openForm({key:edit?`edit-branch:${b.id}`:`new-branch:${threadId}:${sourceMessageId}:${parentId}`,title:edit?'Refine this direction':parentId?'Explore a further branch':'Explore a direction',description:parentId?`A new possibility branching from “${(state.branches||[]).find(x=>x.id===parentId)?.title||'this direction'}”. Start with a name and a hypothesis.`:'Start with a name and a hypothesis. The details can emerge through discussion and evidence.',optionalFrom:edit?null:2,fields:edit?[...branchFields,...comparisonFields.map(name=>({name,label:{demand:'Demand: evidence of a real need',access:'Access: can we reach the customer?',repeatability:'Repeatability: would it recur?',economics:'Economics: estimates and assumptions',effort:'Effort: what would delivery take?',automation:'Automation: what could be repeatable?',uncertainty:'Uncertainty: what remains unknown?'}[name],type:'textarea'}))]:branchFields,initial:b||{},submit:edit?'Save direction':'Create direction',onSubmit:async v=>{let r;if(edit){r=await store.updateBranch(b.id,{...v,expectedRevision:revision})}else{r=await store.createBranch({...v,threadId,parentId,sourceMessageId});newBranchId=r.id;setTimeout(()=>newBranchId='',1000)}branchId=r.id;branchTab='overview';render();toast(edit?'Direction updated.':'New direction attached to the discussion.')}})}
function researchForm(open=false){const b=selectedBranch();if(!open&&!b)return;openForm({key:open?'open-research':`research:${b.id}`,title:open?'Queue outside discovery':'Ask a focused research question',description:'An agent can pick up your question on its next research run. Sourced findings will return here.',fields:[{name:'question',label:'What should the research find out?',required:true,type:'textarea',max:4000,placeholder:open?'Look for recurring problems people already pay to solve…':'Challenge the hypothesis: what evidence would support or weaken it?'}],submit:'Queue research',onSubmit:async v=>{await store.requestResearch({...v,scope:open?'open':'focused',threadId:open?'':threadId,branchId:open?'':b.id});if(!open)branchTab='research';render();toast('Research queued. It is ready for an agent to pick up.')}})}
function findingForm(){const b=selectedBranch();if(!b)return;openForm({key:`finding:${b.id}`,title:'Attach a finding',description:'Keep what the source says distinct from your own interpretation. Your verified account is recorded as the author.',fields:[{name:'title',label:'The finding in one sentence',required:true},{name:'summary',label:'What does it tell us?',type:'textarea',required:true},{name:'stance',label:'How does it affect this direction?',type:'select',default:'neutral',options:[['supports','Supports'],['challenges','Challenges'],['neutral','Neutral / context']]},{name:'evidenceType',label:'What kind of evidence is this?',type:'select',default:'reported',options:[['fact','Fact with source'],['reported','Reported claim'],['inference','Our interpretation'],['question','Open question']]},{name:'sourceUrl',label:'Source URL',type:'url',max:2000,help:'Required for a fact or reported claim. Interpretations and open questions can be saved without a source. Use HTTP or HTTPS.'},{name:'sourceTitle',label:'Source title / publisher'}],submit:'Attach finding',onSubmit:async v=>{await store.addFinding({...v,threadId,branchId:b.id});branchTab='research';render();toast('Finding attached with your authorship.')}})}
function decisionForm(fromComparison=false){const b=selectedBranch();if(!b)return;const revision=b.revision||1;openForm({key:`decision:${b.id}`,title:'Record the decision and the why',description:`For “${b.title}”. Status changes only after the reason is saved.`,backAction:fromComparison?'return-comparison':'close-dialog',backLabel:fromComparison?'Back to comparison':'Close',fields:[{name:'outcome',label:'Our decision',type:'select',options:[['shortlisted','Shortlist — worth testing'],['parked','Park — keep for later'],['rejected','Reject — not this direction'],['reopened','Reopen — explore again']],default:b.status==='rejected'||b.status==='parked'?'reopened':'shortlisted'},{name:'reason',label:'Why are we choosing this?',type:'textarea',required:true},{name:'revisitWhen',label:'What would make us revisit? (optional)',type:'textarea'}],submit:'Record decision',onSubmit:async v=>{await store.recordDecision({...v,threadId,branchId:b.id,expectedRevision:revision});branchTab='decisions';render();toast('Decision and reason recorded.')}})}
function experimentForm(id=''){const e=(state.experiments||[]).find(e=>e.id===id),b=e?(state.branches||[]).find(b=>b.id===e.branchId):selectedBranch();if(!b)return;const revision=e?.revision||1;const fields=[{name:'title',label:'What small test will we run?',required:true},{name:'hypothesis',label:'What are we testing?',type:'textarea',required:true},{name:'method',label:'How will we test it?',type:'textarea',required:true},{name:'successCriterion',label:'What counts as success?',type:'textarea',required:true,help:'Set a clear condition before the experiment starts.'}];if(e)fields.push({name:'status',label:'Experiment status',type:'select',options:['planned','running','completed','stopped']},{name:'result',label:'What actually happened?',type:'textarea',help:'Required when completing. Keep observed results separate from assumptions.'},{name:'learning',label:'What did we learn?',type:'textarea',help:'Required when completing. Explain what the observed result taught us.'},{name:'nextStep',label:'What should we do next?',type:'textarea'});openForm({key:e?`experiment:${e.id}`:`new-experiment:${b.id}`,title:e?'Capture the experiment & result':'Plan a small experiment',description:'An experiment teaches us something. Its outcome doesn’t automatically change the direction’s decision.',fields,initial:e||{hypothesis:b.hypothesis},submit:e?'Save experiment':'Plan experiment',onSubmit:async v=>{if(v.status==='completed'&&(!v.result?.trim()||!v.learning?.trim()))throw new Error('Add both what happened and what you learned before completing this experiment.');if(e)await store.updateExperiment(e.id,{...v,expectedRevision:revision});else await store.createExperiment({...v,threadId:b.threadId,branchId:b.id});branchTab='experiments';render();toast(e?'Experiment updated.':'Experiment planned.')}})}
function showComparison(keepCandidate=false,focusStep=''){if(dialog.open)dialog.close();const rows=branchesForThread();if(!rows.length){toast('Create a direction first, then compare it with other possibilities.');return}if(!keepCandidate||!rows.some(b=>b.id===comparisonId))comparisonId=rows.some(b=>b.id===branchId)?branchId:rows[0].id;const current=Math.max(0,rows.findIndex(b=>b.id===comparisonId)),candidate=rows[current],criteria=[['hypothesis','Hypothesis'],['customer','Customer'],['offer','Offer'],...comparisonFields.map(k=>[k,human(k)])];const evidence=b=>(state.findings||[]).filter(f=>f.branchId===b.id);dialog.className='comparison-dialog';dialog.innerHTML=`<header class="dialog-head"><div><p class="eyebrow">Same questions. Different possibilities.</p><h2 id="dialog-title">Compare directions</h2><p>Unknowns stay visible. Estimates still need evidence.</p></div><button class="icon-button" data-action="close-dialog" aria-label="Close comparison">${icon('close',18)}</button></header><div class="dialog-body"><section class="mobile-comparison" aria-label="Compare one whole direction at a time"><div class="comparison-pager"><button class="secondary small-button" data-compare-step="-1" ${current===0?'disabled':''} aria-label="Previous direction">${icon('back',13)} Previous</button><span class="meta" aria-live="polite">${current+1} of ${rows.length}</span><button class="secondary small-button" data-compare-step="1" ${current===rows.length-1?'disabled':''} aria-label="Next direction">Next ${icon('arrow',13)}</button></div><header class="comparison-candidate"><div class="branch-meta"><span class="eyebrow">${esc(branchCode(candidate))}</span>${badge(candidate.status)}</div><h3 tabindex="-1" id="comparison-candidate-title">${esc(candidate.title)}</h3><div class="inline-actions"><button class="primary small-button" data-compare-decision="${esc(candidate.id)}">Decide on this direction</button><button class="text-button" data-compare-edit="${esc(candidate.id)}">Fill in details →</button></div></header><dl class="comparison-criteria">${criteria.map(([key,label])=>`<div><dt>${esc(label)}</dt><dd class="pre">${esc(text(candidate[key])||'Still to learn')}</dd></div>`).join('')}<div><dt>Evidence & challenges</dt><dd>${evidence(candidate).map(renderFinding).join('')||'No findings attached yet'}</dd></div></dl><div class="comparison-pager comparison-pager-bottom"><button class="secondary small-button" data-compare-step="-1" ${current===0?'disabled':''}>${icon('back',13)} Previous</button><span class="meta">${current+1} of ${rows.length}</span><button class="secondary small-button" data-compare-step="1" ${current===rows.length-1?'disabled':''}>Next ${icon('arrow',13)}</button></div></section><div class="comparison-scroll desktop-comparison" tabindex="0" role="region" aria-label="Direction comparison table, scroll horizontally"><table class="comparison"><thead><tr><th scope="col">Our questions</th>${rows.map(b=>`<th scope="col" class="${b.id===branchId?'comparison-selected':''}"><span class="branch-code">${esc(branchCode(b))}</span>${esc(b.title)}<small>${esc(human(b.status))}</small><button class="text-button" data-compare-edit="${esc(b.id)}">Fill in details →</button><button class="secondary small-button compare-decision" data-compare-decision="${esc(b.id)}">Decide on this direction</button></th>`).join('')}</tr></thead><tbody>${criteria.map(([key,label])=>`<tr><th scope="row">${esc(label)}</th>${rows.map(b=>`<td>${esc(text(b[key])||'Still to learn')}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">Evidence & challenges</th>${rows.map(b=>`<td>${evidence(b).map(f=>`${esc(human(f.stance))}: ${esc(f.title)}${link(f.sourceUrl,f.sourceTitle||'Source')}`).join('<br>')||'No findings attached yet'}</td>`).join('')}</tr></tbody></table></div><div class="dialog-actions"><button class="secondary" data-action="close-dialog">Back to discussion</button></div></div>`;dialog.showModal();if(focusStep){const control=dialog.querySelector(`[data-compare-step="${focusStep}"]:not(:disabled)`);(control||dialog.querySelector('#comparison-candidate-title'))?.focus({preventScroll:true});document.querySelector('#comparison-announcement').textContent=`Direction ${current+1} of ${rows.length}: ${candidate.title}. ${human(candidate.status)}.`}}

function noteForm(){const b=selectedBranch();if(!b)return;openForm({key:`note:${b.id}`,title:'Add a thought to this direction',fields:[{name:'text',label:'Your note',type:'textarea',required:true,max:12000},{name:'sourceUrl',label:'Source URL (optional)',type:'url',max:2000}],submit:'Add note',onSubmit:async v=>{await store.addMessage({...v,threadId,branchId:b.id,kind:v.sourceUrl?'link':'thought'});render();toast('Note saved to this direction.')}})}
async function recordVoice(){voiceThreadId=threadId;if(recorder?.state==='recording'){recorder.stop();return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){voiceNotice='Voice recording isn’t supported in this browser. Add your thought as text instead.';render();return}const capturedThread=threadId;voiceThreadId=capturedThread;try{recordStream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=['audio/webm;codecs=opus','audio/ogg;codecs=opus','audio/mp4'].find(x=>MediaRecorder.isTypeSupported(x));recordChunks=[];recorder=new MediaRecorder(recordStream,{...(mime?{mimeType:mime}:{}),audioBitsPerSecond:32000});recorder.ondataavailable=e=>{if(e.data.size)recordChunks.push(e.data)};recorder.onstop=async()=>{clearInterval(recordTimer);recordStream?.getTracks().forEach(t=>t.stop());const duration=Math.min(60,(Date.now()-recordStart)/1000),blob=new Blob(recordChunks,{type:recorder.mimeType||'audio/webm'});if(blob.size>440000){voiceNotice='This clip is too large to save. Please record a shorter note.';render();return}const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)});audioDraft={data,duration,threadId:capturedThread};voiceNotice=`Original audio ready · ${Math.ceil(duration)} seconds. Add or edit the accompanying text before saving.`;render()};recorder.start();recordStart=Date.now();voiceNotice='Recording · 0 / 60 seconds. Press Stop recording when finished.';recordTimer=setInterval(()=>{const elapsed=Math.floor((Date.now()-recordStart)/1000);voiceNotice=`Recording · ${elapsed} / 60 seconds. Press Stop recording when finished.`;const notice=document.querySelector('.voice-info');if(notice)notice.textContent=voiceNotice;if(elapsed>=60&&recorder.state==='recording')recorder.stop()},500);render()}catch(e){recordStream?.getTracks().forEach(t=>t.stop());voiceNotice=e.name==='NotAllowedError'?'Microphone permission wasn’t granted. You can still add the thought as text.':e.name==='NotFoundError'?'No microphone was found. Add the thought as text instead.':'Recording could not start. Try again or use text.';render()}}
app.addEventListener('change',e=>{if(e.target.id==='discussion-select')navigateThread(e.target.value)});
app.addEventListener('input',e=>{if(e.target.closest('#composer')){const form=e.target.closest('form');setDraft(`composer:${form.dataset.threadId}`,Object.fromEntries(new FormData(form)))}});
dialog.addEventListener('input',e=>{const form=e.target.closest('#studio-form');if(form)setDraft(form.dataset.draftKey,{...Object.fromEntries(new FormData(form)),...(form.dataset.baseRevision?{__baseRevision:Number(form.dataset.baseRevision)}:{})})});
dialog.addEventListener('change',e=>{syncFormRequirements();const form=e.target.closest('#studio-form');if(form)setDraft(form.dataset.draftKey,{...Object.fromEntries(new FormData(form)),...(form.dataset.baseRevision?{__baseRevision:Number(form.dataset.baseRevision)}:{})})});
dialog.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(form.id!=='studio-form'||!formSubmit)return;const button=form.querySelector('[type=submit]'),error=form.querySelector('#form-error');button.disabled=true;error.hidden=true;try{await formSubmit(Object.fromEntries(new FormData(form)));dialog.close()}catch(err){error.textContent=err.message||'Could not save. Your draft is retained. Please try again.';error.hidden=false;error.scrollIntoView({block:'nearest'});button.disabled=false}});
app.addEventListener('submit',async e=>{if(e.target.id!=='composer')return;e.preventDefault();const form=e.target,button=form.querySelector('[type=submit]'),capturedThread=form.dataset.threadId;const values=Object.fromEntries(new FormData(form));if(!values.text?.trim()){toast('Add accompanying text before saving your thought.');return}if(recorder?.state==='recording'){toast('Stop recording before saving this thought.');return}button.disabled=true;try{const clip=audioDraft?.threadId===capturedThread?audioDraft:null;await store.addMessage({threadId:capturedThread,text:values.text,kind:'thought',...(clip?{audioData:clip.data,audioDuration:clip.duration}:{})});clearDraft(`composer:${capturedThread}`);if(clip){audioDraft=null;voiceNotice=''}render();toast('Thought saved. Your original words are kept.')}catch(err){toast(err.message||'Could not save. Your draft is retained.');button.disabled=false}});
function navigateThread(id){if(recorder?.state==='recording')recorder.stop();threadId=id;branchId='';view='studio';render();window.scrollTo({top:0,behavior:'instant'})}
function navigateBranch(id){const b=(state.branches||[]).find(b=>b.id===id);if(!b)return;threadId=b.threadId;branchId=id;branchTab='overview';view='studio';render();if(matchMedia('(max-width:700px)').matches)document.querySelector('.branch-area')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'})}
async function handleClick(e){const el=e.target.closest('button,[data-branch]');if(!el)return;if(el.dataset.view){if(!state.user){toast('Sign in or open the sample to explore the studio.');return}view=el.dataset.view;render();window.scrollTo({top:0,behavior:'instant'});return}if(el.dataset.thread){navigateThread(el.dataset.thread);return}if(el.dataset.branch){navigateBranch(el.dataset.branch);return}if(el.dataset.tab){branchTab=el.dataset.tab;render();return}if(el.dataset.legacyTab){legacyTab=el.dataset.legacyTab;legacyId='';render();return}if(el.dataset.legacy){legacyId=el.dataset.legacy;render();return}if(el.dataset.contextThread){navigateThread(el.dataset.contextThread);if(el.dataset.contextBranch)navigateBranch(el.dataset.contextBranch);return}if(el.dataset.contextLegacy){view='discovery';legacyTab=el.dataset.contextCollection;legacyId=el.dataset.contextLegacy;render();return}if(el.dataset.compareStep){const rows=branchesForThread();const current=rows.findIndex(b=>b.id===comparisonId),next=Math.max(0,Math.min(rows.length-1,current+Number(el.dataset.compareStep)));comparisonId=rows[next].id;showComparison(true,el.dataset.compareStep);return}if(el.dataset.compareDecision){const b=state.branches.find(x=>x.id===el.dataset.compareDecision);if(!b)return;threadId=b.threadId;branchId=b.id;branchTab='decisions';render();decisionForm(true);return}if(el.dataset.compareEdit){const id=el.dataset.compareEdit;dialog.close();navigateBranch(id);branchForm({edit:true});return}const action=el.dataset.action;if(!action)return;if(action==='copy-previous-draft'){try{await navigator.clipboard.writeText(previousDraftCopy);toast('Earlier draft copied. The latest shared fields remain unchanged.')}catch{toast('Select and copy the earlier draft fields shown above.')}return}if(action==='close-dialog'){dialog.close();return}if(action==='sign-in'){el.disabled=true;await act(()=>store.signIn());el.disabled=false;return}if(action==='sign-out'){await act(()=>store.signOut());return}if(action==='refresh'){await act(()=>store.refresh(),'Workspace refreshed.');return}if(!state.user){toast('Open the sample or sign in to begin.');return}switch(action){case'jump-conversation':branchId='';render();document.querySelector('#conversation')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});break;case'jump-directions':document.querySelector('#directions')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});break;case'new-thread':threadForm();break;case'resume':view='studio';branchId='';render();document.querySelector('#thought')?.focus();if(!selectedThread())threadForm();break;case'next-decision':{const b=branchesForThread().find(b=>['exploring','shortlisted'].includes(b.status));if(b){navigateBranch(b.id);branchTab='decisions';render()}else if(selectedThread())branchForm();else threadForm();break}case'edit-thread':{const t=selectedThread();if(!t)return;const revision=t.revision||1;openForm({key:`thread:${t.id}`,title:'Update the discussion',description:'Original messages remain unchanged. You can revise the shared context.',fields:[{name:'title',label:'Discussion title',required:true},{name:'summary',label:'Shared context',type:'textarea'},{name:'status',label:'Discussion status',type:'select',options:['active','parked','closed']}],initial:t,onSubmit:async v=>{await store.updateThread(t.id,{...v,expectedRevision:revision});render();toast('Discussion updated.')}});break}case'new-branch':branchForm();break;case'branch-message':branchForm({sourceMessageId:el.dataset.id});break;case'child-branch':branchForm({parentId:branchId});break;case'edit-branch':branchForm({edit:true});break;case'all-branches':branchId='';render();break;case'compare':case'return-comparison':showComparison();break;case'research':researchForm();break;case'open-research':researchForm(true);break;case'finding':findingForm();break;case'decision':decisionForm();break;case'experiment':experimentForm();break;case'edit-experiment':experimentForm(el.dataset.id);break;case'branch-note':noteForm();break;case'record':await recordVoice();break;case'discard-audio':audioDraft=null;voiceNotice='Clip discarded. Your text draft is still here.';render();break;case'new-signal':openForm({key:'new-signal',title:'Add an outside signal',description:'What did you notice in the market? Attach its source and separate your interpretation.',fields:[{name:'title',label:'What’s the signal?',required:true},{name:'summary',label:'What is happening?',type:'textarea',required:true},{name:'sourceUrl',label:'Source URL',type:'url',max:2000},{name:'market',label:'Market / sector (optional)'},{name:'geography',label:'Geography (optional)'},{name:'initialThought',label:'Your interpretation (optional)',type:'textarea'}],submit:'Add signal',onSubmit:async v=>{const r=await store.addSignal(v);view='discovery';legacyTab='discoveries';legacyId=r.id;render();toast('Market signal saved.')}});break;case'discuss-opportunity':threadForm(legacyId);break;case'legacy-decision':{const r=(state[legacyTab]||[]).find(x=>x.id===legacyId);if(!r)return;openForm({key:`legacy:${legacyTab}:${r.id}`,title:'Keep the decision with its reason',fields:[{name:'status',label:'Record status',type:'select',options:legacyTab==='opportunities'?['candidate','shortlist','parked','rejected']:['new','studied','dismissed']},{name:'reason',label:'Why this decision?',type:'textarea',required:true}],initial:{status:r.status},onSubmit:async v=>{await store.setLegacyStatus(legacyTab,r.id,v.status,v.reason);render();toast('Status and reason saved.')}});break}case'invite':if(!state.isOwner)return;openForm({key:'invite',title:'Add a person to this studio',description:'Only this verified Google email gets editing access. No email is sent automatically.',fields:[{name:'email',label:'Verified Google email',type:'email',required:true,max:254},{name:'name',label:'Name (optional)',max:120}],submit:'Add access',onSubmit:async v=>{shareLink=await store.inviteMember(v.email,v.name);render();toast('Access added. You can copy and share the workspace link.')}});break;case'remove-member':if(!state.isOwner)return;openForm({key:`remove:${el.dataset.email}`,title:'Remove editing access?',description:`${el.dataset.email} will no longer be able to open this workspace. Existing contributions stay.`,fields:[],submit:'Remove access',onSubmit:async()=>{await store.removeMember(el.dataset.email);render();toast('Editing access removed.')}});break;case'copy-share':{const u=new URL(location.origin+location.pathname);u.searchParams.set('workspace',state.ownerUid);try{await navigator.clipboard.writeText(shareLink||u.href);toast('Workspace link copied.')}catch{toast('Copy the workspace link shown above.')}break}case'switch-workspace':openForm({key:'switch-workspace',title:'Open a shared workspace',description:'Paste its link. Access still requires your verified Google email to be a member.',fields:[{name:'url',label:'Workspace link',type:'url',required:true,max:2000}],submit:'Open workspace',onSubmit:async v=>{const u=new URL(v.url);if(u.origin!==location.origin)throw new Error('Use a shared link from this studio’s website.');const id=u.searchParams.get('workspace');if(!id)throw new Error('This link does not select a workspace.');await store.switchWorkspace(id);threadId='';branchId='';render()}});break;case'my-workspace':await act(()=>store.switchWorkspace(state.user.uid));break}}
app.addEventListener('click',e=>{handleClick(e).catch(err=>toast(err.message||'Something went wrong. Please try again.'))});dialog.addEventListener('click',e=>{handleClick(e).catch(err=>toast(err.message||'Something went wrong. Please try again.'))});
